import json

with open('/tmp/neg_experiments.json') as f:
    experiments = json.load(f)

def get(eid, field, default=''):
    return experiments[eid].get(field, default) or default

def metrics(eid):
    return experiments[eid].get('metrics', {})

def short_hyp(eid, maxlen=80):
    h = get(eid, 'hypothesis')
    if len(h) > maxlen:
        return h[:maxlen-3] + '...'
    return h

# Detailed extraction for each experiment
for eid in sorted(experiments.keys()):
    m = metrics(eid)
    # Extract key eval metrics
    eval_final = None
    eval_peak = None
    nve_peak = None

    for k, v in m.items():
        if 'eval_return_final' in k or 'eval_return' == k:
            eval_final = v
        if 'eval_peak' in k or 'peak_eval' in k or 'eval_return_peak' in k:
            eval_peak = v
        if 'nve_peak' in k or 'peak_nve' in k:
            nve_peak = v

    # Also check for final eval from trajectory
    if eval_final is None:
        for k in sorted(m.keys()):
            if k.startswith('eval_return_') and k[-1].isdigit():
                eval_final = m[k]  # last one

    print(f'{eid} | eval_peak={eval_peak} | eval_final={eval_final} | nve_peak={nve_peak}')
